export const AUDIO_MANIFEST: AudioManifest = {
  schema: "longyu-audio-manifest/1",
  generatedAt: "2026-10-01T09:36:51.000Z",
  version: AUDIO_MANIFEST_VERSION,
  entries: [...CANONICAL_AUDIO_ENTRIES],
};

const BY_ID: Readonly<Record<string, CanonicalAudioEntry>> = Object.fromEntries(
  CANONICAL_AUDIO_ENTRIES.map((e) => [e.audioId, e])
);

const BY_TEXT: Readonly<Record<string, CanonicalAudioEntry>> = Object.fromEntries(
  CANONICAL_AUDIO_ENTRIES.map((e) => [e.textKey, e])
);

export const CANONICAL_AUDIO_ASSETS: Readonly<Record<string, string>> = Object.fromEntries(
  CANONICAL_AUDIO_ENTRIES.map((e) => [e.textKey, e.uri])
);

export function audioEntryById(audioId: string | null | undefined): CanonicalAudioEntry | null {
  if (!audioId) return null;
  return BY_ID[audioId] ?? null;
}

export function audioEntryByText(text: string | null | undefined): CanonicalAudioEntry | null {
  const clean = String(text ?? "").trim();
  if (!clean) return null;
  return BY_TEXT[clean] ?? BY_TEXT[clean.replace(/[！？。，、]/g, "")] ?? null;
}

export function resolveCanonicalUri(input: { audioId?: string | null; text?: string | null }): string | null {
  const byId = audioEntryById(input.audioId);
  if (byId) return byId.uri;
  return audioEntryByText(input.text)?.uri ?? null;
}

export function isCorePackAudio(audioId: string | null | undefined): boolean {
  return audioEntryById(audioId)?.pack === "core";
}
